      phase.hashCode ^
      sourceId.hashCode ^
      filesFound.hashCode ^
      processed.hashCode ^
      total.hashCode ^
      currentPath.hashCode ^
      error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreScanUpdate &&
          runtimeType == other.runtimeType &&
          phase == other.phase &&
          sourceId == other.sourceId &&
          filesFound == other.filesFound &&
          processed == other.processed &&
          total == other.total &&
          currentPath == other.currentPath &&
          error == other.error;
}

/// One group of [`CoreLibrary::search_grouped`].
class CoreSearchGroup {
  final CoreItemKind kind;

  /// Best first.
  final List<CoreItem> items;

  const CoreSearchGroup({required this.kind, required this.items});

  @override
  int get hashCode => kind.hashCode ^ items.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreSearchGroup &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          items == other.items;
}

/// A media source.
class CoreSource {
  final PlatformInt64 id;

  /// `local`, `smb` or `webdav`.
  final String kind;
  final String name;

  /// `file:///…`, `smb://host/share/dir` or `https://…`, without credentials.
  final String uri;
  final String? username;

  /// Local path of a `file://` root.
  final String? localRoot;

  /// Followed by the change watcher ([`CoreLibrary::start_watcher`]).
  final bool autoScan;

  const CoreSource({
    required this.id,
    required this.kind,
    required this.name,
    required this.uri,
    this.username,
