      id.hashCode ^
      kind.hashCode ^
      name.hashCode ^
      uri.hashCode ^
      username.hashCode ^
      localRoot.hashCode ^
      autoScan.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreSource &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          kind == other.kind &&
          name == other.name &&
          uri == other.uri &&
          username == other.username &&
          localRoot == other.localRoot &&
          autoScan == other.autoScan;
}

